warp:
shader_body
{
vec2 _uv = uv;

    vec2 v1 = vec2(normalize(uv_orig-0.5));
    vec2 v2 = v1.yx * vec2(1.0,-1.0);

    float z = length(texsize.zw)*450.0;

    _uv.xy += v1*texsize.zw * cos(rad*170.0 - time*7.0)*1.0;
    _uv.xy += v2*texsize.zw * cos(ang*30.0 - time*7.0)*2.0;

    // sample previous frame
    ret = texture( sampler_main, _uv ).xyz;



    // darken (decay) over time
    ret = (ret - 0.002)*0.99;


}

comp:
shader_body
{
  //rad = fract(rad*2.0);
  rad = pow(rad,2.0)*3.5;


  float ang2 = fract(ang/6.28*9.0 + time*0.05);
  vec2 uv2 = 0.5 + rad*0.5*vec2(cos(ang2),sin(ang2));    

  uv = uv2;
  //uv = mix(uv, uv2, 0.5 + 0.5*cos(ang + time*3.0));


  ret = texture(sampler_main, uv).xyz;

  vec3 orig = vec3(ret);
  ret = lum(ret);
  ret.x = orig.x;

  ret = -0.3 + 1.6*ret;
}
